import wandb
api = wandb.Api()

# Try all entities and look for freige-grpo or similar projects
for entity in ['xiaoyucorynne-', 'VAE-HOI-team']:
    try:
        projects = api.projects(entity)
        for p in projects:
            if 'freige' in p.name.lower() or 'grpo' in p.name.lower() or 'faith' in p.name.lower():
                print(f'MATCH: {entity}/{p.name}')
                # List recent runs
                runs = api.runs(f'{entity}/{p.name}', order='-created_at', per_page=10)
                for r in runs:
                    print(f'  run: id={r.id} name={r.name} state={r.state}')
    except Exception as e:
        print(f'Error for {entity}: {e}')

# Also try default entity
print()
print('Searching all projects for recent runs with extract/flatnli in name...')
for entity in ['xiaoyucorynne-', 'VAE-HOI-team']:
    try:
        projects = api.projects(entity)
        for p in projects:
            try:
                runs = api.runs(f'{entity}/{p.name}', filters={'state': 'running'}, per_page=5)
                for r in runs:
                    if 'extract' in r.name.lower() or 'flatnli' in r.name.lower() or 'grpo' in r.name.lower() or 'ced' in r.name.lower():
                        print(f'FOUND: {entity}/{p.name} - id={r.id} name={r.name} state={r.state}')
